class Rule:
    """Base class for the rules exposed to consumers.

    Instances compare equal to other rules with the same type/value, and also to
    plain mappings (``{'type': 'char', 'value': [...]}``), which keeps them easy
    to assert against.
    """

    type: RuleType
    __slots__ = ()

