import { describe, test, expect } from 'vitest';
import { Graph, RulesBuilder, buildRuleStack, RuleChar, RuleCharExclude, RuleEnd, RuleRef, isRange, GrammarParseError } from 'gbnf';
import { getSerializedRuleKey } from '../src/grammar-graph/get-serialized-rule-key';
import { GenericSet } from '../src/grammar-graph/generic-set';
import { getInputAsCodePoints } from '../src/grammar-graph/get-input-as-code-points';
import { parseChar } from '../src/rules-builder/parse-char';
import { parseName } from '../src/rules-builder/parse-name';
import { parseSpace } from '../src/rules-builder/parse-space';

test('parseChar', () => {
  expect([['a',[97,1]],['\\n',[10,2]],['\\r',[13,2]],['\\t',[9,2]],['\\\\',[92,2]],['\\"',[34,2]],['\\[',[91,2]],['\\]',[93,2]],['\\x41',[65,4]],['é',[0xe9,1]],['\\u00e9',[0xe9,6]],['\\U0001F600',[0x1f600,10]]].map(([s]) => parseChar(s as string, 0)))
    .toEqual([[97,1],[10,2],[13,2],[9,2],[92,2],[34,2],[91,2],[93,2],[65,4],[0xe9,1],[0xe9,6],[0x1f600,10]]);
  expect(() => parseChar('\\q', 0)).toThrowError(/Unknown escape/);
  expect(() => parseChar('', 0)).toThrowError(/Unexpected end of grammar input/);
});

test('parseName / parseSpace', () => {
  expect([parseName('root ::= x',0), parseName('foo-bar ::= x',0), parseName('  abc',2), parseName('MixedCase',0)]).toEqual(['root','foo-bar','abc','MixedCase']);
  expect(() => parseName('::= x',0)).toThrowError(/Failed to find a valid name/);
  expect(() => parseName('foo1',0)).toThrowError(/Invalid character/);
  expect([['   a',0,false,3],['\t\t a',0,false,3],['\n\n a',0,false,0],['\n\n a',0,true,3],['# comment\na',0,false,9],['# comment\na',0,true,10],['abc',0,true,0],['',0,true,0]]
    .map(([s,p,n]) => parseSpace(s as string, p as number, n as boolean)))
    .toEqual([3,3,0,3,9,10,0,0]);
});

test('RulesBuilder', () => {
  expect(new RulesBuilder('root ::= "a" | [b-d]').rules).toEqual([[
    {type:'CHAR',value:[97]},{type:'ALT'},{type:'CHAR',value:[98]},{type:'CHAR_RNG_UPPER',value:100},{type:'END'},
  ]]);
  expect([...new RulesBuilder('root ::= foo\nfoo ::= "a"').symbolIds]).toEqual([['root',0],['foo',1]]);
  const q = new RulesBuilder('root ::= "a"*');
  expect(q.rules.length).toBe(2);
  expect(q.rules[1]![q.rules[1]!.length - 1].type).toBe('END');
  expect(() => new RulesBuilder('root ::= missing')).toThrowError(/Undefined rule identifier/);
  expect(() => new RulesBuilder('root ::= "aaaaaaaaaaaaaaaaaaaaaaaaaaaaa"', 0)).toThrowError(/duration of 0 exceeded/);
});

test('buildRuleStack', () => {
  expect(buildRuleStack(new RulesBuilder('root ::= "ab" | [c-e]').rules[0]!)).toEqual([
    [{type:'char',value:[97]},{type:'char',value:[98]},{type:'end'}],
    [{type:'char',value:[[99,101]]},{type:'end'}],
  ]);
  const refStack = buildRuleStack(new RulesBuilder('root ::= foo\nfoo ::= "a"').rules[0]!);
  expect(refStack[0][0]).toBeInstanceOf(RuleRef);
  expect((refStack[0][0] as RuleRef).value).toBe(1);
  expect(buildRuleStack(new RulesBuilder('root ::= [abc]').rules[0]!)[0][0]).toEqual({type:'char',value:[97,98,99]});
});

test('isRange / codePoints / serialized keys', () => {
  expect([[1,2],[1],[1,2,3],1,undefined,['a','b']].map(v => isRange(v))).toEqual([true,false,false,false,false,false]);
  expect([getInputAsCodePoints('ab'), getInputAsCodePoints(97), getInputAsCodePoints([97,98]), getInputAsCodePoints(''), getInputAsCodePoints('é')])
    .toEqual([[97,98],[97],[97,98],[],[0xe9]]);
  expect([getSerializedRuleKey(new RuleEnd()), getSerializedRuleKey(new RuleChar([97])), getSerializedRuleKey(new RuleChar([[97,122]])), getSerializedRuleKey(new RuleCharExclude([97])), getSerializedRuleKey(new RuleRef(4))])
    .toEqual(['0','1-[97]','1-[[97,122]]','2-[97]','3-4']);
  expect(() => getSerializedRuleKey({} as never)).toThrowError(/Unknown rule type/);
});

test('GenericSet', () => {
  const gs = new GenericSet<{id:number}, number>(i => i.id);
  const first = {id:1}, duplicate = {id:1}, second = {id:2};
  gs.add(first); gs.add(duplicate); gs.add(second);
  expect(gs.size).toBe(2);
  expect([...gs]).toEqual([first, second]);
  expect(gs.has(first)).toBe(true);
  expect(gs.has(duplicate)).toBe(false);
  expect(gs.get(duplicate)).toBe(first);
  gs.delete(first); gs.delete(second);
  expect(gs.size).toBe(0);
  expect(() => gs.delete(first)).toThrowError(/Could not get ref/);
});

test('Graph print', () => {
  const grammar = 'root ::= "ab"';
  const graph = new Graph(grammar, new RulesBuilder(grammar).rules.map(r => buildRuleStack(r!)), 0);
  expect(graph.print(undefined, false)).toBe('\n{0,0,0}[a]-> {0,0,1}[b]-> {0,0,2}end');
  expect(graph.print(undefined, true)).toContain('\x1b[');
  expect(() => new Graph(grammar, new RulesBuilder(grammar).rules.map(r => buildRuleStack(r!)), 99)).toThrowError(/Root node not found/);
});

test('RuleRef nodes', () => {
  expect(() => new RuleRef(0).nodes).toThrowError(/Nodes are not set/);
  const ref = new RuleRef(0);
  ref.nodes = [];
  expect(ref.nodes).toEqual([]);
});
