import { test, expect } from 'vitest';
import GBNF, { GrammarParseError, InputParseError } from 'gbnf';
import { buildErrorPosition, GRAMMAR_PARSER_ERROR_HEADER_MESSAGE } from '../src/utils/errors/build-error-position';
import { GRAMMAR_PARSER_ERROR_HEADER_MESSAGE as HDR } from '../src/utils/errors/grammar-parse-error';
import { INPUT_PARSER_ERROR_HEADER_MESSAGE } from '../src/utils/errors/input-parse-error';
import { getInputAsString } from '../src/utils/errors/get-input-as-string';

test('grammar parse error messages', () => {
  const cases: [string, string][] = [
    ['root ::= missing', 'Failed to parse grammar: Undefined rule identifier "missing"\n\nroot ::= missing\n         ^'],
    ['root ::= "a"\nfoo1 ::= "b"', 'Failed to parse grammar: Invalid character "1" when parsing name, only lowercase letters and hyphens are allowed.\n\nroot ::= "a"\nfoo1 ::= "b"\n    ^'],
    ['root "a"', 'Failed to parse grammar: Expecting ::= at 5\n\nroot "a"\n     ^'],
    ['root ::= *', 'Failed to parse grammar: Expecting preceding item to */+/? at 9\n\nroot ::= *\n         ^'],
    ['root ::= ("a"', 'Failed to parse grammar: Expecting \')\' at 13\n\nroot ::= ("a"\n\n^'],
    ['root ::= "\\q"', 'Failed to parse grammar: Unknown escape at \\\n\nroot ::= "\\q"\n          ^'],
    ['', 'Failed to parse grammar: No rules were found\n\nNo input provided'],
    ['# just a comment', 'Failed to parse grammar: No rules were found\n\n# just a comment\n^'],
  ];
  for (const [grammar, message] of cases) {
    let caught: unknown;
    try { GBNF(grammar); } catch (e) { caught = e; }
    expect(caught).toBeInstanceOf(GrammarParseError);
    expect((caught as Error).message).toBe(message);
  }
});

test('grammar parse error attributes / missing root', () => {
  try { GBNF('root ::= missing'); } catch (e) {
    const err = e as GrammarParseError;
    expect([err.grammar, err.reason, err.pos, err.name]).toEqual(['root ::= missing', 'Undefined rule identifier "missing"', 9, 'GrammarParseError']);
  }
  expect(() => GBNF('a ::= "b"')).toThrowError(/Grammar does not contain a root symbol/);
});

test('input parse errors', () => {
  try { GBNF('root ::= "yes"', 'yq'); } catch (e) {
    const err = e as InputParseError;
    expect(err.message).toBe('Failed to parse input string:\n\nyq\n ^');
    expect(err.src).toBe('yq');
    expect(err.pos).toBe(1);
    expect(err.errorForMostRecentInput).toBe('Failed to parse input string:\n\nyq\n ^');
  }
  const state = GBNF('root ::= "yes"', 'y');
  try { state.add('q'); } catch (e) {
    const err = e as InputParseError;
    expect(err.message).toBe('Failed to parse input string:\n\nyq\n ^');
    expect(err.src).toBe('yq');
    expect(err.errorForMostRecentInput).toBe('Failed to parse input string:\n\nq\n^');
  }
  try { GBNF('root ::= "a"', 'b'); } catch (e) { expect((e as Error).name).toBe('InputParseError'); }
});

test('buildErrorPosition and helpers', () => {
  expect(buildErrorPosition('', 0)).toEqual(['No input provided']);
  expect(buildErrorPosition('abc', 0)).toEqual(['abc', '^']);
  expect(buildErrorPosition('abc', 2)).toEqual(['abc', '  ^']);
  expect(buildErrorPosition('abc\ndef\nghi', 5)).toEqual(['abc', 'def', '  ^']);
  expect(buildErrorPosition('a\nb\nc\nd\ne', 8).length).toBe(4);
  expect(HDR('nope')).toBe('Failed to parse grammar: nope');
  expect(INPUT_PARSER_ERROR_HEADER_MESSAGE).toBe('Failed to parse input string:');
  expect([getInputAsString('abc'), getInputAsString(97), getInputAsString([97, 98]), getInputAsString('')]).toEqual(['abc', 'a', 'ab', '']);
});
